#!/usr/bin/env node
const args = process.argv.slice(2);

let upper = false;
let repeat = 1;
const positional = [];

for (let i = 0; i < args.length; i++) {
  const a = args[i];
  if (a === "--upper") {
    upper = true;
  } else if (a === "--repeat") {
    repeat = parseInt(args[++i], 10);
    if (Number.isNaN(repeat) || repeat < 1) repeat = 1;
  } else if (a.startsWith("--repeat=")) {
    repeat = parseInt(a.slice("--repeat=".length), 10);
    if (Number.isNaN(repeat) || repeat < 1) repeat = 1;
  } else {
    positional.push(a);
  }
}

const text = positional[0] || "";
const result = upper ? text.toUpperCase() : text;

if (repeat === 1) {
