const { execFileSync } = require("child_process");
const path = require("path");

const cli = path.join(__dirname, "cli.js");

function run(args) {
  return execFileSync(process.execPath, [cli, ...args], { encoding: "utf8" });
}

let pass = 0;

function assertEqual(name, actual, expected) {
  if (actual === expected) {
    pass++;
    console.log(`ok - ${name}`);
  } else {
    console.error(`not ok - ${name}`);
    console.error(`  expected: ${JSON.stringify(expected)}`);
    console.error(`  actual:   ${JSON.stringify(actual)}`);
    process.exit(1);
  }
}

// N=3: repeats the uppercased line three times.
assertEqual("repeat 3", run(["--upper", "--repeat", "3", "hi"]), "HI\nHI\nHI\n");
// Default (flag absent): prints once.
assertEqual("default once", run(["--upper", "hi"]), "HI\n");
// --repeat=2 form.
assertEqual("repeat=2", run(["--upper", "--repeat=2", "hi"]), "HI\nHI\n");

console.log(`\n${pass} test(s) passed`);

